/**
 * Defines how an offspring of an entity is born
 * @minecraft minecraft:offspring
 */
export type OffspringComponent = {
  /**
   * If true, the entities will blend their attributes in the offspring after they breed.
   * @default true
   * @minecraft blend_attributes
   */
  blendAttributes?: boolean;
  /**
   * Chance of a baby that does not inherit the parents' variant.
   * @minecraft deny_parents_variant
   */
  denyParentsVariant?: {
    /**
     * The percentage chance of denying the parents` variant.
     * @default 0
     * @minecraft chance
     */
    chance?: number;
    /**
     * The inclusive maximum of the variant range.
     * @default 0
     * @minecraft max_variant
     */
    maxVariant?: number;
    /**
     * The inclusive minimum of the variant range.
     * @default 0
     * @minecraft min_variant
     */
    minVariant?: number;
  };
  /**
   * Determines how likely the babies are to NOT inherit one of their parent's variances. Values are between 0.0 and 1.0, with a higher number meaning more likely to mutate.
   * @minecraft mutation_factor
   */
  mutationFactor?: {
    /**
     * The percentage chance of the offspring getting its color as if spawned rather than inheriting color from its parents.
     * @default 0
     * @minecraft color
     */
    color?: number;
    /**
     * The percentage chance of a mutation on the entity's extra variant type.
     * @default 0
     * @minecraft extra_variant
     */
    extraVariant?: number;
    /**
     * The percentage chance of a mutation on the entity's variant type.
     * @default 0
     * @minecraft variant
     */
    variant?: number;
  };
  /**
   * Strategy used for mutating variants and extra variants for offspring. Current valid alternatives are 'random' and 'none'.
   * @default "none"
   * @minecraft mutation_strategy
   */
  mutationStrategy?: string;
  /**
   * [EXPERIMENTAL] List of attributes that should benefit from parent centric attribute blending. For example, horses blend their health, movement, and jump_strength in their offspring.
   * @minecraft parent_centric_attribute_blending
   */
  parentCentricAttributeBlending?: unknown[];
  /**
   * Entity properties copied from the parents (1.26.50).
   * @minecraft property_inheritance
   */
  propertyInheritance?: {
    /**
     * The chance it should not inherit from either parent
     * @minecraft mutation_chance
     */
    mutationChance?: number;
    /**
     * Array of values to select from if mutating and the component has random mutation set
     * @minecraft mutation_values
     */
    mutationValues?: unknown[];
  } & Record<string, unknown>;
  /**
   * Range used to determine random extra variant.
   * @default 0
   * @minecraft random_extra_variant_mutation_interval
   */
  randomExtraVariantMutationInterval?: [number, number];
  /**
   * Range used to determine random variant.
   * @default 0
   * @minecraft random_variant_mutation_interval
   */
  randomVariantMutationInterval?: [number, number];
  /**
   * If true, the babies will be automatically tamed if its parents are.
   * @default true
   * @minecraft inherit_tamed
   */
  inheritTamed?: boolean;
  /**
   * If true, the babies will have their color be mixed.
   * @default true
   * @minecraft combine_parent_colors
   */
  combineParentColors?: boolean;
  /**
   * Key-Value Pair of the other entity and the offspring to spawn
   * @minecraft offspring_pairs
   */
  offspringPairs?: Record<string, string>;
};

